// *** IR Dump After InlineElementals ***
module @_QMgeometry_types {
  // Derived types declared as fir.type
  fir.type @_QTgeometry_typesTVec3 {x: f32, y: f32, z: f32}
  fir.type @_QTgeometry_typesTParticle {
    position: !fir.type<@_QTgeometry_typesTVec3>,
    velocity: !fir.type<@_QTgeometry_typesTVec3>,
    mass: f32,
    id: i32
  }

  func.func @_QPadvance_particle(
      %arg0: !fir.ref<!fir.type<@_QTgeometry_typesTParticle>> {fir.bindc_name = "p", fir.inout},
      %arg1: !fir.ref<f32> {fir.bindc_name = "dt", fir.in}
  ) {
    %dt = fir.load %arg1 : !fir.ref<f32>

    // p%position%x — two-level field navigation
    %pos_idx = fir.field_index position, !fir.type<@_QTgeometry_typesTParticle>
    %pos_ptr = fir.coordinate_of %arg0, %pos_idx
                 : (!fir.ref<!fir.type<@_QTgeometry_typesTParticle>>,
                    !fir.field) -> !fir.ref<!fir.type<@_QTgeometry_typesTVec3>>

    %x_idx   = fir.field_index x, !fir.type<@_QTgeometry_typesTVec3>
    %px_ptr  = fir.coordinate_of %pos_ptr, %x_idx
                 : (!fir.ref<!fir.type<@_QTgeometry_typesTVec3>>,
                    !fir.field) -> !fir.ref<f32>

    %px_val  = fir.load %px_ptr : !fir.ref<f32>   // p%position%x (RHS)

    // p%velocity%x
    %vel_idx = fir.field_index velocity, !fir.type<@_QTgeometry_typesTParticle>
    %vel_ptr = fir.coordinate_of %arg0, %vel_idx
                 : (!fir.ref<!fir.type<@_QTgeometry_typesTParticle>>,
                    !fir.field) -> !fir.ref<!fir.type<@_QTgeometry_typesTVec3>>
    %vx_ptr  = fir.coordinate_of %vel_ptr, %x_idx
                 : (!fir.ref<!fir.type<@_QTgeometry_typesTVec3>>,
                    !fir.field) -> !fir.ref<f32>
    %vx_val  = fir.load %vx_ptr : !fir.ref<f32>   // p%velocity%x

    %prod    = arith.mulf %vx_val, %dt fastmath<contract> : f32  // vx * dt
    %new_px  = arith.addf %px_val, %prod fastmath<contract> : f32 // px + vx*dt
    fir.store %new_px to %px_ptr : !fir.ref<f32>  // p%position%x = ...

    // (y and z components follow same pattern)
    return
  }
}
