// *** IR Dump After HLFIR Lowering ***
module @_QMgeometry_types {
  fir.type @_QTgeometry_typesTVec3 {x: f32, y: f32, z: f32}
  fir.type @_QTgeometry_typesTParticle {
    position: !fir.type<@_QTgeometry_typesTVec3>,
    velocity: !fir.type<@_QTgeometry_typesTVec3>,
    mass: f32, id: i32
  }

  func.func @_QPadvance_particle(
      %arg0: !fir.ref<!fir.type<@_QTgeometry_typesTParticle>> {fir.bindc_name = "p", fir.inout},
      %arg1: !fir.ref<f32>  {fir.bindc_name = "dt", fir.in}
  ) {
    // hlfir.declare for scalar derived-type variable
    %p:2 = hlfir.declare %arg0
        {fortran_attrs = #fir.var_attrs<intent_inout>, uniq_name = "_QFadvance_particleEp"}
        : (!fir.ref<!fir.type<@_QTgeometry_typesTParticle>>)
       -> (!fir.ref<!fir.type<@_QTgeometry_typesTParticle>>,
           !fir.ref<!fir.type<@_QTgeometry_typesTParticle>>)

    %dt:2 = hlfir.declare %arg1
        {fortran_attrs = #fir.var_attrs<intent_in>, uniq_name = "_QFadvance_particleEdt"}
        : (!fir.ref<f32>) -> (!fir.ref<f32>, !fir.ref<f32>)

    %dt_val = fir.load %dt#0 : !fir.ref<f32>

    // Navigate: p%position%x — chain of fir.coordinate_of
    %fi_pos = fir.field_index position, !fir.type<@_QTgeometry_typesTParticle>
    %fi_x   = fir.field_index x,        !fir.type<@_QTgeometry_typesTVec3>
    %fi_vel = fir.field_index velocity, !fir.type<@_QTgeometry_typesTParticle>

    %pos_ref = fir.coordinate_of %p#0, %fi_pos : (!fir.ref<...>, !fir.field) -> !fir.ref<!fir.type<@_QTgeometry_typesTVec3>>
    %px_ref  = fir.coordinate_of %pos_ref, %fi_x : (!fir.ref<...>, !fir.field) -> !fir.ref<f32>
    %px_val  = fir.load %px_ref : !fir.ref<f32>

    %vel_ref = fir.coordinate_of %p#0, %fi_vel : (!fir.ref<...>, !fir.field) -> !fir.ref<!fir.type<@_QTgeometry_typesTVec3>>
    %vx_ref  = fir.coordinate_of %vel_ref, %fi_x : (!fir.ref<...>, !fir.field) -> !fir.ref<f32>
    %vx_val  = fir.load %vx_ref : !fir.ref<f32>

    %prod   = arith.mulf %vx_val, %dt_val fastmath<contract> : f32
    %new_px = arith.addf %px_val, %prod   fastmath<contract> : f32
    fir.store %new_px to %px_ref : !fir.ref<f32>

    // (y, z components analogous)
    return
  }
}
